// 1) this.http.get<Cliente>(`/clientes/${id}`)      → termina (exemplo)
// 2) this.chatService.novaMensagem$   (Subject do hub do chat)
// 3) this.filtroForm.valueChanges      (campo de busca de documentos)
// 4) this.documentoService.listar(clienteId)   (por dentro faz this.http.get)

ngOnInit() {
  this.clienteService.obter(this.id)            // A (HTTP)
    .subscribe(c => this.cliente = c);

  this.chatService.novaMensagem$               // B (Subject do hub)
    .subscribe(m => console.log('nova', m));

  this.documentoService.listar(this.id)         // C (HTTP)
    .subscribe(d => this.documentos = d);
}

